568	func TestSubmitReviewConcurrentNoOverwrite(t *testing.T) {
569		dir := t.TempDir()
570		mustReplay(t, dir, twoFindingsInput)
571	
572		const n = 12
573		var wg sync.WaitGroup
574		errs := make([]error, n)
575		start := make(chan struct{})
576		for i := 0; i < n; i++ {
577			wg.Add(1)
578			go func(i int) {
579				defer wg.Done()
580				<-start
581				_, errs[i] = SubmitReview(dir, reviewSub("1", "0xa", "0xv", "sandwich",
582					fmt.Sprintf("s-%d", i), "op", "r", ReviewStatusReal, 0))
583			}(i)
584		}
585		close(start)
586		wg.Wait()
587	
588		succeeded, busy, other := 0, 0, 0
589		for _, err := range errs {
590			switch {
591			case err == nil:
592				succeeded++
593			case errors.Is(err, ErrBusy):
594				busy++
595			default:
596				other++
597				t.Errorf("unexpected error: %v", err)
598			}
599		}
600		if other != 0 {
601			t.FailNow()
602		}
603		if succeeded != 1 {
604			t.Fatalf("got %d successes and %d busy, want exactly 1 success", succeeded, busy)
605		}
606		hist, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
607		if err != nil {
608			t.Fatal(err)
609		}
610		if hist.Version != 1 || len(hist.Revisions) != 1 {
611			t.Fatalf("concurrent submissions corrupted history: %+v", hist)
612		}
613		// A follower that based its submission on version 0 now gets a conflict
614		// instead of silently overwriting the winner's revision.
615		if _, err := SubmitReview(dir, reviewSub("1", "0xa", "0xv", "sandwich", "late", "op", "r", ReviewStatusReal, 0)); !errors.Is(err, ErrReviewConflict) {
