1	package mevwatch
2	
3	import (
4		"bufio"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"math"
10		"os"
11		"path/filepath"
12		"sort"
13		"strings"
14		"syscall"
15	)
16	
17	// Block is one validated, deduplicated input block. Swaps are kept in
18	// canonical order: exact duplicates removed, sorted by Index.
19	type Block struct {
20		ChainID     string
21		BlockHash   string
22		BlockNumber int64
23		Swaps       []Swap
24	}
25	
26	// ReportFinding is one risk conclusion inside a block report. Evidence
27	// carries the raw fields of every swap that participated in the judgment.
28	type ReportFinding struct {
29		Kind     string `json:"kind"`
30		Severity int    `json:"severity"`
31		TxHash   string `json:"txHash"`
32		Evidence []Swap `json:"evidence"`
33	}
34	
35	// Report is the archived per-block risk report. Version records the full
36	// rule parameters that produced the findings, so the report stays
37	// interpretable without the original rule definition.
38	type Report struct {
39		ChainID     string          `json:"chainId"`
40		BlockHash   string          `json:"blockHash"`
41		BlockNumber int64           `json:"blockNumber"`
42		SwapCount   int             `json:"swapCount"`
43		Version     RuleVersion     `json:"version"`
44		Findings    []ReportFinding `json:"findings"`
45	}
46	
47	// LineError pins a replay failure to a 1-based input line.
48	type LineError struct {
49		Line int
50		Err  error
51	}
52	
53	func (e *LineError) Error() string { return fmt.Sprintf("line %d: %v", e.Line, e.Err) }
54	func (e *LineError) Unwrap() error { return e.Err }
55	
56	// ErrBusy reports an archive locked by another process.
57	var ErrBusy = errors.New("archive is busy")
58	
59	// ErrUnknownBlock reports a query for a block that was never archived.
60	var ErrUnknownBlock = errors.New("unknown block")
61	
62	type blockID struct {
63		chainID   string
64		blockHash string
65	}
66	
67	// blockLine mirrors one input line. Pointers distinguish a missing field
68	// from an explicit zero value.
69	type blockLine struct {
70		ChainID     *string `json:"chainId"`
71		BlockHash   *string `json:"blockHash"`
72		BlockNumber *int64  `json:"blockNumber"`
73		Swaps       *[]Swap `json:"swaps"`
74	}
75	
76	func parseBlock(text string) (Block, error) {
77		var raw blockLine
78		dec := json.NewDecoder(strings.NewReader(text))
79		if err := dec.Decode(&raw); err != nil {
80			return Block{}, fmt.Errorf("invalid JSON: %w", err)
81		}
82		if dec.More() {
83			return Block{}, errors.New("invalid JSON: unexpected trailing data")
84		}
85		if raw.ChainID == nil || *raw.ChainID == "" {
86			return Block{}, errors.New("chainId must be a non-empty string")
87		}
88		if raw.BlockHash == nil || *raw.BlockHash == "" {
89			return Block{}, errors.New("blockHash must be a non-empty string")
90		}
91		if raw.BlockNumber == nil {
92			return Block{}, errors.New("blockNumber is required")
93		}
94		if *raw.BlockNumber < 0 {
95			return Block{}, fmt.Errorf("blockNumber must be non-negative, got %d", *raw.BlockNumber)
96		}
97		if raw.Swaps == nil {
98			return Block{}, errors.New("swaps must be an array")
99		}
100	
101		byTx := make(map[string]Swap)
102		byIndex := make(map[int]string)
103		swaps := []Swap{}
104		for i, s := range *raw.Swaps {
105			if s.TxHash == "" {
106				return Block{}, fmt.Errorf("swaps[%d]: TxHash must not be empty", i)
107			}
108			if s.Pool == "" {
109				return Block{}, fmt.Errorf("swaps[%d]: Pool must not be empty", i)
110			}
111			if s.Trader == "" {
112				return Block{}, fmt.Errorf("swaps[%d]: Trader must not be empty", i)
113			}
114			if s.In < 0 || s.Out < 0 || s.GasPrice < 0 || s.Index < 0 {
115				return Block{}, fmt.Errorf("swaps[%d]: In, Out, GasPrice and Index must be non-negative", i)
116			}
117			if prev, ok := byTx[s.TxHash]; ok {
118				if prev != s {
119					return Block{}, fmt.Errorf("swaps[%d]: conflicting records for tx %s", i, s.TxHash)
120				}
121				continue // exact duplicate, keep one copy
122			}
123			if other, ok := byIndex[s.Index]; ok {
124				return Block{}, fmt.Errorf("swaps[%d]: Index %d already used by tx %s", i, s.Index, other)
125			}
126			byTx[s.TxHash] = s
127			byIndex[s.Index] = s.TxHash
128			swaps = append(swaps, s)
129		}
130		sort.Slice(swaps, func(i, j int) bool { return swaps[i].Index < swaps[j].Index })
131		return Block{
132			ChainID:     *raw.ChainID,
133			BlockHash:   *raw.BlockHash,
134			BlockNumber: *raw.BlockNumber,
135			Swaps:       swaps,
136		}, nil
137	}
138	
139	func swapsEqual(a, b []Swap) bool {
140		if len(a) != len(b) {
141			return false
142		}
143		for i := range a {
144			if a[i] != b[i] {
145				return false
146			}
147		}
148		return true
149	}
150	
151	// sameContent reports whether two blocks carry the same content. Both sides
152	// are canonical (deduplicated, sorted by Index), so ordering and exact
153	// duplicates in the input do not affect the comparison.
154	func sameContent(blockNumber int64, swaps []Swap, b Block) bool {
155		return blockNumber == b.BlockNumber && swapsEqual(swaps, b.Swaps)
156	}
157	
158	// gasDominates reports whether front strictly exceeds victim*multiplier,
159	// staying correct when victim is zero or near math.MaxInt64.
160	func gasDominates(front, victim int64, multiplier int64) bool {
161		return victim <= math.MaxInt64/multiplier && front > victim*multiplier
162	}
163	
164	// DetectBlock checks every swap against its adjacent neighbours within its
165	// pool under the built-in rules. See DetectBlockWithRules.
166	func DetectBlock(swaps []Swap) []ReportFinding {
167		return DetectBlockWithRules(swaps, BuiltinVersion().Rules)
168	}
169	
170	// DetectBlockWithRules checks every swap against its adjacent neighbours
171	// within its pool: a sandwich when the same trader brackets the victim with
172	// higher gas on both sides, otherwise a displacement when the previous
173	// swap's gas strictly exceeds the configured multiple of the victim's. The
174	// last swap of a pool is checked too. An enabled sandwich takes priority
175	// over displacement for the same victim; with the sandwich rule off the
176	// victim can still be flagged for displacement. With both rules off the
177	// result is an empty slice.
178	func DetectBlockWithRules(swaps []Swap, rules RuleSet) []ReportFinding {
179		pools := make(map[string][]Swap)
180		for _, s := range swaps {
181			pools[s.Pool] = append(pools[s.Pool], s)
182		}
183		findings := []ReportFinding{}
184		for _, pool := range pools {
185			sort.Slice(pool, func(i, j int) bool { return pool[i].Index < pool[j].Index })
186			for i, victim := range pool {
187				var front, back *Swap
188				if i > 0 {
189					front = &pool[i-1]
190				}
191				if i+1 < len(pool) {
192					back = &pool[i+1]
193				}
194				if rules.Sandwich.Enabled && front != nil && back != nil &&
195					front.Trader == back.Trader && front.Trader != victim.Trader &&
196					front.GasPrice > victim.GasPrice && back.GasPrice > victim.GasPrice {
197					findings = append(findings, ReportFinding{
198						Kind: "sandwich", Severity: rules.Sandwich.Severity, TxHash: victim.TxHash,
199						Evidence: []Swap{*front, victim, *back},
200					})
201					continue
202				}
203				if rules.Displacement.Enabled && front != nil &&
204					gasDominates(front.GasPrice, victim.GasPrice, int64(rules.Displacement.Multiplier)) {
205					findings = append(findings, ReportFinding{
206						Kind: "displacement", Severity: rules.Displacement.Severity, TxHash: victim.TxHash,
207						Evidence: []Swap{*front, victim},
208					})
209				}
210			}
211		}
212		sort.Slice(findings, func(i, j int) bool {
213			if findings[i].Severity != findings[j].Severity {
214				return findings[i].Severity > findings[j].Severity
215			}
216			return findings[i].TxHash < findings[j].TxHash
217		})
218		return findings
219	}
220	
221	// record is the archived form of a block: the report plus the canonical
222	// swaps, so a later import can detect content conflicts. Version carries
223	// the full rule parameters used for the findings; it is nil only in
224	// archives written before rule versions existed, which are interpreted
225	// under the built-in rules.
226	type record struct {
227		ChainID     string          `json:"chainId"`
228		BlockHash   string          `json:"blockHash"`
229		BlockNumber int64           `json:"blockNumber"`
230		Swaps       []Swap          `json:"swaps"`
231		Findings    []ReportFinding `json:"findings"`
232		Version     *RuleVersion    `json:"version,omitempty"`
233	}
234	
235	func (r record) id() blockID { return blockID{r.ChainID, r.BlockHash} }
236	
237	func (r record) ruleVersion() RuleVersion {
238		if r.Version != nil {
239			return *r.Version
240		}
241		return BuiltinVersion()
242	}
243	
244	func (r record) report() Report {
245		return Report{
246			ChainID:     r.ChainID,
247			BlockHash:   r.BlockHash,
248			BlockNumber: r.BlockNumber,
249			SwapCount:   len(r.Swaps),
250			Version:     r.ruleVersion(),
251			Findings:    r.Findings,
252		}
253	}
254	
255	const (
256		archiveFileName = "archive.json"
257		lockFileName    = "lock"
258	)
259	
260	type archiveData struct {
261		Records []record `json:"records"`
262		// Versions and EnabledVersion are absent in archives written before
263		// rule versions existed; such archives run the built-in rules.
264		Versions       []RuleVersion `json:"versions,omitempty"`
265		EnabledVersion string        `json:"enabledVersion,omitempty"`
266		// Suppressions and AlertRecords are absent in archives written before
267		// offline alerting existed; such archives simply have no registered
268		// conditions and no processing history.
269		Suppressions []Suppression      `json:"suppressions,omitempty"`
270		AlertRecords []ProcessingRecord `json:"alerts,omitempty"`
271		// Reviews is absent in archives written before manual reviews existed;
272		// every conclusion then behaves as unreviewed.
273		Reviews []ReviewObject `json:"reviews,omitempty"`
274	}
275	
276	func readArchive(dir string) (archiveData, error) {
277		raw, err := os.ReadFile(filepath.Join(dir, archiveFileName))
278		if errors.Is(err, os.ErrNotExist) {
279			return archiveData{Records: []record{}}, nil
280		}
281		if err != nil {
282			return archiveData{}, err
283		}
284		var data archiveData
285		if err := json.Unmarshal(raw, &data); err != nil {
286			return archiveData{}, fmt.Errorf("archive is corrupted: %w", err)
287		}
288		return data, nil
289	}
290	
291	// writeArchiveAtomic replaces the archive file in one rename, so a crash
292	// can only expose the previous or the next complete commit, never a half
293	// written file.
294	func writeArchiveAtomic(dir string, data archiveData) error {
295		raw, err := json.MarshalIndent(data, "", "  ")
296		if err != nil {
297			return err
298		}
299		tmp := filepath.Join(dir, archiveFileName+".tmp")
300		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
301		if err != nil {
302			return err
303		}
304		if _, err := f.Write(raw); err != nil {
305			f.Close()
306			os.Remove(tmp)
307			return err
308		}
309		if err := f.Sync(); err != nil {
310			f.Close()
311			os.Remove(tmp)
312			return err
313		}
314		if err := f.Close(); err != nil {
315			os.Remove(tmp)
316			return err
317		}
318		if err := os.Rename(tmp, filepath.Join(dir, archiveFileName)); err != nil {
319			os.Remove(tmp)
320			return err
321		}
322		if d, err := os.Open(dir); err == nil {
323			d.Sync()
324			d.Close()
325		}
326		return nil
327	}
328	
329	// lockArchive takes an flock on the archive's lock file. The lock is
330	// released automatically if the process dies, so no stale locks survive.
331	func lockArchive(dir string, how int) (*os.File, error) {
332		f, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
333		if err != nil {
334			return nil, err
335		}
336		if err := syscall.Flock(int(f.Fd()), how); err != nil {
337			f.Close()
338			if errors.Is(err, syscall.EWOULDBLOCK) {
339				return nil, ErrBusy
340			}
341			return nil, err
342		}
343		return f, nil
344	}
345	
346	type parsedBlock struct {
347		line  int
348		block Block
349	}
350	
351	func parseBlocks(r io.Reader) ([]parsedBlock, error) {
352		var out []parsedBlock
353		reader := bufio.NewReader(r)
354		lineNo := 0
355		for {
356			raw, err := reader.ReadBytes('\n')
357			if len(raw) > 0 {
358				lineNo++
359			}
360			if text := strings.TrimSpace(string(raw)); text != "" {
361				block, perr := parseBlock(text)
362				if perr != nil {
363					return nil, &LineError{Line: lineNo, Err: perr}
364				}
365				out = append(out, parsedBlock{line: lineNo, block: block})
366			}
367			if err == io.EOF {
368				return out, nil
369			}
370			if err != nil {
371				return nil, err
372			}
373		}
374	}
375	
